dataSet.query:
ВЫБРАТЬ ЭтапПроизводства2_2.Дата КАК ДатаЭтапа, ЭтапПроизводства2_2.Статус КАК Статус, ЭтапПроизводства2_2.Подразделение КАК Подразделение, ЭтапПроизводства2_2.Организация КАК Организация, ЭтапПроизводства2_2.Спецификация КАК Спецификация, ЭтапПроизводства2_2ВыходныеИзделия.Номенклатура КАК НоменклатураВыходногоИзделия, ЭтапПроизводства2_2ВыходныеИзделия.Характеристика КАК ХарактеристикаВыходногоИзделия, ЭтапПроизводства2_2ОбеспечениеМатериаламиИРаботами.Номенклатура КАК НоменклатураМатериала, ЭтапПроизводства2_2ОбеспечениеМатериаламиИРаботами.Характеристика КАК ХарактеристикаМатериала, ЭтапПроизводства2_2.Ссылка КАК Этап, ЭтапПроизводства2_2.Распоряжение КАК ЗаказНаПроизводство, ЭтапПроизводства2_2.Назначение КАК Назначение //{ДОПОЛНИТЕЛЬНЫЕ_ПОЛЯ_БАЗА} ПОМЕСТИТЬ База ИЗ Документ.ЭтапПроизводства2_2.ВыходныеИзделия КАК ЭтапПроизводства2_2ВыходныеИзделия ЛЕВОЕ СОЕДИНЕНИЕ Документ.ЭтапПроизводства2_2 КАК ЭтапПроизводства2_2 ПРАВОЕ СОЕДИНЕНИЕ Документ.ЭтапПроизводства2_2.ОбеспечениеМатериаламиИРаботами КАК ЭтапПроизводства2_2ОбеспечениеМатериаламиИРаботами ПО (ЭтапПроизводства2_2ОбеспечениеМатериаламиИРаботами.Ссылка = ЭтапПроизводства2_2.Ссылка) ПО ЭтапПроизводства2_2ВыходныеИзделия.Ссылка = ЭтапПроизводства2_2.Ссылка //{ДОПОЛНИТЕЛЬНЫЕ_СОЕДИНЕНИЯ_БАЗА} ГДЕ ЭтапПроизводства2_2.Дата между &НачалоПериода и &КонецПериода И ЭтапПроизводства2_2.Этап.бит_ЭтоЭтапРаскроя = Истина {ГДЕ ЭтапПроизводства2_2.Дата, ЭтапПроизводства2_2.Статус.*, ЭтапПроизводства2_2.Подразделение.*, ЭтапПроизводства2_2.Организация.*, ЭтапПроизводства2_2.Спецификация.*, ЭтапПроизводства2_2ВыходныеИзделия.Номенклатура.*, ЭтапПроизводства2_2ВыходныеИзделия.Характеристика.*, ЭтапПроизводства2_2ОбеспечениеМатериаламиИРаботами.Номенклатура.*, ЭтапПроизводства2_2ОбеспечениеМатериаламиИРаботами.Характеристика.*, ЭтапПроизводства2_2.Ссылка.*, ЭтапПроизводства2_2.Распоряжение.*, ЭтапПроизводства2_2.Назначение.*} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗЛИЧНЫЕ ЭтапПроизводства2_2ВидыРабочихЦентров.ВидРабочегоЦентра КАК ВидРабочегоЦентра, База.Этап КАК Этап ПОМЕСТИТЬ втВРЦ ИЗ Документ.ЭтапПроизводства2_2.ВидыРабочихЦентров КАК ЭтапПроизводства2_2ВидыРабочихЦентров ВНУТРЕННЕЕ СОЕДИНЕНИЕ База КАК База ПО (ЭтапПроизводства2_2ВидыРабочихЦентров.Использовать) и ЭтапПроизводства2_2ВидыРабочихЦентров.Ссылка = База.Этап {ГДЕ ЭтапПроизводства2_2ВидыРабочихЦентров.ВидРабочегоЦентра.*, База.Этап.*}
ОБЪЕДИНИТЬ
ВЫБРАТЬ РАЗЛИЧНЫЕ ЭтапПроизводства2_2АльтернативныеВидыРабочихЦентров.ВидРабочегоЦентра, База.Этап ИЗ Документ.ЭтапПроизводства2_2.АльтернативныеВидыРабочихЦентров КАК ЭтапПроизводства2_2АльтернативныеВидыРабочихЦентров ВНУТРЕННЕЕ СОЕДИНЕНИЕ База КАК База ПО (ЭтапПроизводства2_2АльтернативныеВидыРабочихЦентров.Использовать) и ЭтапПроизводства2_2АльтернативныеВидыРабочихЦентров.Ссылка = База.Этап {ГДЕ ЭтапПроизводства2_2АльтернативныеВидыРабочихЦентров.ВидРабочегоЦентра.*, База.Этап.*} ; //////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗЛИЧНЫЕ Максимум(ЭтапПроизводства2_2Трудозатраты.ВидРабот) КАК ВидРабот, База.Этап КАК Этап ПОМЕСТИТЬ втВидыРабот ИЗ Документ.ЭтапПроизводства2_2.Трудозатраты КАК ЭтапПроизводства2_2Трудозатраты ВНУТРЕННЕЕ СОЕДИНЕНИЕ База КАК База ПО ЭтапПроизводства2_2Трудозатраты.Ссылка = База.Этап {ГДЕ ЭтапПроизводства2_2Трудозатраты.ВидРабот.*, База.Этап.*} СГРУППИРОВАТЬ ПО База.Этап ; //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
ВЫБРАТЬ РАЗЛИЧНЫЕ База.Этап, естьnull(бит_ПакетЭтаповНаРаскройПроизводственныеЭтапы.Ссылка, значение(Документ.бит_ПакетЭтаповНаРаскрой.ПустаяСсылка)) КАК ПакетРаскроя Поместить втПакетыРаскроя из База как база Левое соединение Документ.бит_ПакетЭтаповНаРаскрой.ПроизводственныеЭтапы КАК бит_ПакетЭтаповНаРаскройПроизводственныеЭтапы По База.Этап = бит_ПакетЭтаповНаРаскройПроизводственныеЭтапы.Ссылка и бит_ПакетЭтаповНаРаскройПроизводственныеЭтапы.Ссылка.Проведен {ГДЕ База.Этап.*} ; ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////// //----------------------------------------------------------------------------------------- ВЫБРАТЬ РАЗЛИЧНЫЕ База.Этап КАК Этап, База.Назначение КАК Назначение, База.ЗаказНаПроизводство КАК ЗаказНаПроизводство, База.Назначение.Заказ КАК ЗаказНазначения, ЗаказНаПроизводство2_2Продукция.Номенклатура КАК Номенклатура, ЗаказНаПроизводство2_2Продукция.Характеристика КАК Характеристика ПОМЕСТИТЬ втКлючиЗаказовКлиентов ИЗ База КАК База Внутреннее СОЕДИНЕНИЕ Документ.ЗаказНаПроизводство2_2.Продукция КАК ЗаказНаПроизводство2_2Продукция ПО ЗаказНаПроизводство2_2Продукция.Ссылка = База.ЗаказНаПроизводство И ЗаказНаПроизводство2_2Продукция.Назначение = База.Назначение {ГДЕ База.Этап.*} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗЛИЧНЫЕ втКлючиЗаказовКлиентов.Этап КАК Этап, втКлючиЗаказовКлиентов.ЗаказНазначения КАК Заказ0, ТоварыЗаказаНаПеремещение1.Назначение.Заказ КАК Заказ1, ТоварыЗаказаНаПеремещение2.Назначение.Заказ КАК Заказ2 ПОМЕСТИТЬ втРазборЗаказовКлиентов ИЗ втКлючиЗаказовКлиентов КАК втКлючиЗаказовКлиентов ЛЕВОЕ СОЕДИНЕНИЕ Документ.ЗаказНаПеремещение.Товары КАК ТоварыЗаказаНаПеремещение1 ПО ТоварыЗаказаНаПеремещение1.Ссылка = ВЫРАЗИТЬ(втКлючиЗаказовКлиентов.ЗаказНазначения КАК Документ.ЗаказНаПеремещение) ЛЕВОЕ СОЕДИНЕНИЕ Документ.ЗаказНаПеремещение.Товары КАК ТоварыЗаказаНаПеремещение2 ПО ТоварыЗаказаНаПеремещение2.Ссылка = ВЫРАЗИТЬ(ТоварыЗаказаНаПеремещение1.Назначение.Заказ КАК Документ.ЗаказНаПеремещение) И ТоварыЗаказаНаПеремещение2.Номенклатура = втКлючиЗаказовКлиентов.Номенклатура И ТоварыЗаказаНаПеремещение2.Характеристика = втКлючиЗаказовКлиентов.Характеристика {ГДЕ втКлючиЗаказовКлиентов.Этап.*} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗЛИЧНЫЕ втРазборЗаказовКлиентов.Этап КАК Этап, ВЫБОР КОГДА втРазборЗаказовКлиентов.Заказ0 ССЫЛКА Документ.ЗаказКлиента ТОГДА ВЫРАЗИТЬ(втРазборЗаказовКлиентов.Заказ0 КАК Документ.ЗаказКлиента) КОГДА втРазборЗаказовКлиентов.Заказ1 ССЫЛКА Документ.ЗаказКлиента ТОГДА ВЫРАЗИТЬ(втРазборЗаказовКлиентов.Заказ1 КАК Документ.ЗаказКлиента) КОГДА втРазборЗаказовКлиентов.Заказ2 ССЫЛКА Документ.ЗаказКлиента ТОГДА ВЫРАЗИТЬ(втРазборЗаказовКлиентов.Заказ2 КАК Документ.ЗаказКлиента) ИНАЧЕ ЗНАЧЕНИЕ(Документ.ЗаказКлиента.ПустаяСсылка) КОНЕЦ КАК ЗаказКлиента ПОМЕСТИТЬ втЗаказыКлиентов ИЗ втРазборЗаказовКлиентов КАК втРазборЗаказовКлиентов {ГДЕ втРазборЗаказовКлиентов.Этап.*} ;
//------------------------------------------------------------------------------------------
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ втВРЦ.ВидРабочегоЦентра КАК ВидРабочегоЦентра, База.ДатаЭтапа КАК ДатаЭтапа, База.Статус КАК Статус, База.Статус КАК Состояние, База.Подразделение КАК Подразделение, База.Организация КАК Организация, База.Спецификация КАК Спецификация, База.НоменклатураВыходногоИзделия КАК НоменклатураВыходногоИзделия, База.ХарактеристикаВыходногоИзделия КАК ХарактеристикаВыходногоИзделия, База.НоменклатураМатериала КАК НоменклатураМатериала, База.ХарактеристикаМатериала КАК ХарактеристикаМатериала, База.Этап КАК Этап, База.ЗаказНаПроизводство КАК ЗаказНаПроизводство, База.Назначение КАК Назначение, втПакетыРаскроя.ПакетРаскроя КАК ПакетРаскроя, ЕСТЬNULL(СостоянияЭтаповПроизводства.СостояниеОбеспечения, Значение(Перечисление.СостоянияОбеспеченияЭтапаПроизводства.ПустаяСсылка)) = ЗНАЧЕНИЕ(Перечисление.СостоянияОбеспеченияЭтапаПроизводства.ОжидаетсяОбеспечение) КАК Обеспечено, СТРОКА(База.Этап.КоличествоУпаковокПлан) + " поз: " + База.Спецификация.ОсновноеИзделиеНоменклатура.Наименование КАК Состав, втВидыРабот.ВидРабот, втЗаказыКлиентов.ЗаказКлиента КАК ЗаказКлиента
//{ДОПОЛНИТЕЛЬНЫЕ_ПОЛЯ_ИТОГ} ИЗ База КАК База ЛЕВОЕ СОЕДИНЕНИЕ втВРЦ КАК втВРЦ ПО База.Этап = втВРЦ.Этап ЛЕВОЕ СОЕДИНЕНИЕ втВидыРабот КАК втВидыРабот ПО База.Этап = втВидыРабот.Этап Левое соединение втПакетыРаскроя КАК втПакетыРаскроя по База.Этап = втПакетыРаскроя.Этап ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СостоянияЭтаповПроизводства КАК СостоянияЭтаповПроизводства ПО База.ЗаказНаПроизводство = СостоянияЭтаповПроизводства.Распоряжение И База.Этап = СостоянияЭтаповПроизводства.Этап ЛЕВОЕ СОЕДИНЕНИЕ втЗаказыКлиентов КАК втЗаказыКлиентов ПО База.Этап = втЗаказыКлиентов.Этап {ГДЕ втВРЦ.ВидРабочегоЦентра.*, База.ДатаЭтапа, База.Статус.*, База.Подразделение.*, База.Организация.*, База.Спецификация.*, База.НоменклатураВыходногоИзделия.*, База.ХарактеристикаВыходногоИзделия.*, База.НоменклатураМатериала.*, База.ХарактеристикаМатериала.*, База.Этап.*, База.ЗаказНаПроизводство.*, База.Назначение.*, втПакетыРаскроя.ПакетРаскроя.*, втВидыРабот.ВидРабот.*, втЗаказыКлиентов.ЗаказКлиента.* //{ДОПОЛНИТЕЛЬНЫЕ_ПОЛЯ_ГДЕ} }
